import type { Person } from './person';
type BaseRecord = {
    id: string;
    createTimestamp: number;
    lastUpdatedByPerson?: Person;
    parentId?: undefined;
    updateTimestamp: number;
    isActive: boolean;
};
type VersionedRecord = Omit<BaseRecord, 'parentId'> & {
    parentId: string;
};
export type JoltRecord<Versioned extends boolean = false> = Versioned extends true ? VersionedRecord : BaseRecord;
export {};
